+	sequence?: number;
+	sessionId?: string;
+	timestamp?: number;
+	payload?: unknown;
+};
+
+export type HubReply = {
+	ok: boolean;
+	payload?: Record<string, unknown>;
+	error?: { code?: string; message?: string };
+};
+
+export type HubResolvedEndpoint = {
+	url: string;
+	authToken?: string;
+};
