+	resolveUrl(scope: HubLinkScope): Promise<string | undefined>;
+	/** Optional richer resolver returning `{ url, authToken }`, re-read on every reconnect. */
+	resolveEndpoint?(
+		scope: HubLinkScope,
+	): Promise<HubResolvedEndpoint | undefined>;
+	createClient(
+		url: string,
+		scope: HubLinkScope,
+		authToken?: string,
+	): HubClientPort;
+	sleep(ms: number): Promise<void>;
+};
